#!/usr/bin/env python3
"""Expand the initial native source bundle; removed after the first CI commit."""
import base64, gzip, hashlib, json, os
from pathlib import Path
root = Path(__file__).resolve().parent
payload = json.loads(gzip.decompress(base64.b64decode("")))
for item in payload["files"]:
    destination = root / item["path"]
    if root not in destination.resolve().parents:
        raise RuntimeError("A source path leaves the repository")
    data = base64.b64decode(item["data"])
    if hashlib.sha256(data).hexdigest() != item["sha256"]:
        raise RuntimeError("Source checksum mismatch")
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(data)
    destination.chmod(item["mode"])
for item in payload["links"]:
    if item != {"path": "CLAUDE.md", "target": "AGENTS.md"}:
        raise RuntimeError("Unexpected symbolic link")
    destination = root / item["path"]
    if destination.is_symlink() or destination.exists():
        destination.unlink()
    os.symlink(item["target"], destination)
print("Initialized native source files and CLAUDE.md -> AGENTS.md")
